package com.alsafa.native4;
import android.app.*;import android.graphics.Color;import android.os.*;import android.text.*;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.util.*;
/** Full repair intake with real multi-part inventory reservation on Native4 core. */
public final class CoreRepairPanelBinder{
 private final Activity a;private final Native4Services services;private final TextView status;private final EditText customer,phone,watch,total;private final Spinner currency,account;private final LinearLayout partRows;private final RepairDeliveryDialog delivery;private final Handler handler=new Handler(Looper.getMainLooper());
 private static final class PartRow{LinearLayout root;EditText search,qty;Spinner results;ArrayList<RepairPartStore.SearchResult> items=new ArrayList<>();Runnable pending;}
 public CoreRepairPanelBinder(Activity a,Native4Services s,TextView st){this.a=a;services=s;status=st;delivery=new RepairDeliveryDialog(a,s,st);customer=a.findViewById(R.id.repairCustomer);phone=a.findViewById(R.id.repairPhone);watch=a.findViewById(R.id.repairWatch);total=a.findViewById(R.id.repairTotal);currency=a.findViewById(R.id.repairCurrency);account=a.findViewById(R.id.repairAccount);partRows=a.findViewById(R.id.repairPartRows);currency.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,AccountingChoices.CURRENCY_LABELS));account.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"الدفع عند التسليم / لاحقًا","الدرج","شام كاش","الخزنة الخارجية","البنك"}));prepare(customer);prepare(phone);prepare(watch);prepare(total);a.findViewById(R.id.addRepairPart).setOnClickListener(v->addPartRow());Button save=a.findViewById(R.id.saveRepair);save.setOnClickListener(v->save());addPartRow();}
 private void prepare(EditText e){e.setGravity(Gravity.END);e.setMinHeight(dp(56));e.setTextSize(16);e.setPadding(dp(14),dp(8),dp(14),dp(8));e.setBackgroundResource(R.drawable.alsafa_card);}
 private void addPartRow(){PartRow pr=new PartRow();pr.root=new LinearLayout(a);pr.root.setOrientation(LinearLayout.VERTICAL);pr.root.setPadding(0,dp(6),0,dp(6));pr.search=new EditText(a);pr.search.setHint("اسم القطعة أو الباركود");prepare(pr.search);pr.results=new Spinner(a);pr.results.setMinimumHeight(dp(52));pr.qty=new EditText(a);pr.qty.setHint("الكمية");pr.qty.setInputType(android.text.InputType.TYPE_CLASS_NUMBER);pr.qty.setText("1");prepare(pr.qty);Button remove=new Button(a);remove.setText("✕ حذف هذه القطعة");remove.setOnClickListener(v->{partRows.removeView(pr.root);if(partRows.getChildCount()==0)addPartRow();});pr.root.addView(pr.search);pr.root.addView(pr.results);pr.root.addView(pr.qty);pr.root.addView(remove);partRows.addView(pr.root);pr.root.setTag(pr);pr.search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int b,int c){if(pr.pending!=null)handler.removeCallbacks(pr.pending);pr.pending=()->refresh(pr);handler.postDelayed(pr.pending,325);}public void afterTextChanged(Editable e){}});}
 private void refresh(PartRow pr){pr.items.clear();String q=pr.search.getText().toString().trim();if(!q.isEmpty())pr.items.addAll(services.repairParts.search(q,20));ArrayList<String> labels=new ArrayList<>();for(RepairPartStore.SearchResult r:pr.items)labels.add(r.name+" — المتاح "+r.quantity+(r.barcode==null||r.barcode.isEmpty()?"":" — "+r.barcode));if(labels.isEmpty())labels.add("لا توجد نتائج");pr.results.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,labels));}
 private void save(){try{String c=customer.getText().toString().trim(),ph=phone.getText().toString().trim(),w=watch.getText().toString().trim(),at=total.getText().toString().trim();if(w.isEmpty())throw new IllegalArgumentException("وصف الساعة أو الصيانة مطلوب");if(at.isEmpty())throw new IllegalArgumentException("قيمة الصيانة المتفق عليها مطلوبة");double amount=Double.parseDouble(at);if(amount<0||!Double.isFinite(amount))throw new IllegalArgumentException("قيمة الصيانة غير صحيحة");String cur=AccountingChoices.codeAt(AccountingChoices.CURRENCY_CODES,currency.getSelectedItemPosition()),pay=paymentCode(account.getSelectedItemPosition());if("SHAM_CASH".equals(pay)&&"TRY".equals(cur))throw new IllegalArgumentException("شام كاش يقبل الدولار والليرة السورية فقط");ArrayList<RepairWorkflowStore.PartRequest> parts=new ArrayList<>();for(int i=0;i<partRows.getChildCount();i++){PartRow pr=(PartRow)partRows.getChildAt(i).getTag();String q=pr.search.getText().toString().trim();if(q.isEmpty())continue;int pos=pr.results.getSelectedItemPosition();if(pr.items.isEmpty()||pos<0||pos>=pr.items.size())throw new IllegalArgumentException("اختر نتيجة صحيحة لكل قطعة صيانة");int qty=Integer.parseInt(pr.qty.getText().toString().trim());if(qty<=0)throw new IllegalArgumentException("كمية قطعة الصيانة غير صحيحة");parts.add(new RepairWorkflowStore.PartRequest(pr.items.get(pos).partId,qty));}String id=services.repairs.receiveWithParts(c,ph,w,amount,cur,pay,parts);Native4BackgroundSync.request(a);DeveloperDashboardPanelBinder.refreshActive();customer.setText("");phone.setText("");watch.setText("");total.setText("");account.setSelection(0);partRows.removeAllViews();addPartRow();status.setText("✓ تم استلام الصيانة — المتفق عليه: "+fmt(amount)+" "+cur);showNextAction(id,amount,cur);}catch(Exception e){status.setText("لم تُحفظ الصيانة: "+msg(e));}}
 private void showNextAction(String id,double amount,String cur){new AlertDialog.Builder(a).setTitle("تم استلام الصيانة").setMessage("القيمة المتفق عليها: "+fmt(amount)+" "+cur+"\n\nعند التسليم تستطيع تحصيل كامل المبلغ أو جزء منه، أو تعديل السعر النهائي بعد مفاصلة العميل.").setNegativeButton("العودة",null).setPositiveButton("تحصيل / تسليم",(d,w)->delivery.show(id)).show();}
 private static String paymentCode(int p){if(p==1)return "CASH";if(p==2)return "SHAM_CASH";if(p==3)return "EXTERNAL";if(p==4)return "BANK";return "LATER";}private int dp(int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static String fmt(double v){return String.format(Locale.US,"%.2f",v);}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
}